import{_ as a,o as i,c as e,a3 as n}from"./chunks/framework.CohJ1kFH.js";const c=JSON.parse('{"title":"Chapter 7.1 Milvus 3.0 环境升级","description":"","frontmatter":{},"headers":[],"relativePath":"Milvus/chapter7/7.1-Milvus3.0环境升级.md","filePath":"Milvus/chapter7/7.1-Milvus3.0环境升级.md","lastUpdated":1793868172000}'),l={name:"Milvus/chapter7/7.1-Milvus3.0环境升级.md"};function p(t,s,r,o,h,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="chapter-7-1-milvus-3-0-环境升级" tabindex="-1">Chapter 7.1 Milvus 3.0 环境升级 <a class="header-anchor" href="#chapter-7-1-milvus-3-0-环境升级" aria-label="Permalink to &quot;Chapter 7.1 Milvus 3.0 环境升级&quot;">​</a></h1><h2 id="_7-1-0-这一章干什么" tabindex="-1">7.1.0 这一章干什么 <a class="header-anchor" href="#_7-1-0-这一章干什么" aria-label="Permalink to &quot;7.1.0 这一章干什么&quot;">​</a></h2><p>这一章干一件事：把 Docker Compose 部署的 Milvus 2.6 升级到 3.0，升完之后想用新功能，知道去哪改配置。</p><p>写作基线：<strong>Milvus v3.0.2</strong>。</p><p><strong>参考文档</strong>：<a href="https://milvus.io/docs/zh/upgrade_milvus_standalone-docker.md" target="_blank" rel="noreferrer">使用 Docker Compose 升级 Milvus Standalone</a> · <a href="https://milvus.io/docs/zh/release_notes.md" target="_blank" rel="noreferrer">Milvus 发布说明</a></p><h2 id="_7-1-1-升级步骤-docker-compose" tabindex="-1">7.1.1 升级步骤（Docker Compose） <a class="header-anchor" href="#_7-1-1-升级步骤-docker-compose" aria-label="Permalink to &quot;7.1.1 升级步骤（Docker Compose）&quot;">​</a></h2><p>先看官方验证记录：「升级过程中保留了 etcd、MinIO、Woodpecker 以及现有的数据目录，仅将 Milvus 镜像更换为 milvusdb/milvus:v3.0.2。」——保留的是官方验证环境里的依赖；你的部署有什么依赖就保留什么，唯一要动的只有 Milvus 镜像。</p><p><strong>升级前准备</strong>：</p><ul><li>由 Docker Compose 管理的现有 Milvus 2.6.x Standalone 部署；</li><li>用于现有部署的 Docker Compose 文件和配置；</li><li>Milvus 元数据和持久化数据的最新备份。</li></ul><p>注意：「请勿在此过程中替换当前的 Compose 文件或更改依赖项版本。请保留现有的 etcd、对象存储、消息队列、卷和配置。仅更新 Milvus 镜像标签。」</p><p><strong>步骤 1：备份当前配置。</strong> 保存当前 Compose 文件以及所有已挂载的 Milvus 配置文件的副本，然后确认当前容器状态正常（实际按你的文件名操作）：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-compose-before-upgrade.yml</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>元数据和持久化数据的备份是先决条件；官方安装文档推荐了 Milvus Backup——「一款用于 Milvus 数据备份的开源工具」。</p><p><strong>步骤 2：更新 Milvus 镜像。</strong> 在现有 Compose 文件中，只把 <code>standalone</code> 服务的镜像改成目标版本：</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">services</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  standalone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    image</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">milvusdb/milvus:v3.0.2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>拉取目标镜像，并仅重新创建 Milvus 容器：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --detach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>官方说明：「Docker Compose 会保持现有的 etcd 和 object-storage 容器继续运行，并复用已配置的数据目录。」</p><p><strong>步骤 3：验证升级。</strong> 先查容器状态、镜像版本和日志：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> images</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>验证 standalone 服务状态正常，且现有 Collections 仍可进行查询和搜索。在启用任何 v3.0.2 专属功能之前，请先完成这些检查。</p><p><strong>注意事项</strong>：</p><ul><li><strong>消息队列别换。</strong> 官方：「升级至 Milvus v3.0.2 时，必须保留当前的消息队列选择。升级过程中不支持在不同的消息队列系统之间切换。未来版本将支持更改消息队列系统。」</li><li><strong>别手动降级。</strong> 官方：「本操作流程不支持通过将 Milvus 镜像降级回 2.6.x 版本来执行降级或回滚。在 v3.0.2 写入数据后，仅回滚镜像的操作可能无法读取更新后的状态。如果升级失败，请停止写入操作，并使用恢复方案来还原升级前的元数据和持久化数据备份。请先在非生产环境中验证该恢复方案。」</li></ul><p><strong>参考文档</strong>：<a href="https://milvus.io/docs/zh/upgrade_milvus_standalone-docker.md" target="_blank" rel="noreferrer">使用 Docker Compose 升级 Milvus Standalone</a></p><h2 id="_7-1-2-启用-storage-v3" tabindex="-1">7.1.2 启用 Storage V3 <a class="header-anchor" href="#_7-1-2-启用-storage-v3" aria-label="Permalink to &quot;7.1.2 启用 Storage V3&quot;">​</a></h2><p>升级本身不会启用任何新功能。官方原文：「Storage V3 默认处于禁用状态。」后面的快照、TEXT 字段、外部 Collection都依赖Storage V3，用到时需要手动打开。</p><p><strong>改什么配置</strong>：<code>milvus-standalone</code> 容器中的 <code>/milvus/configs/user.yaml</code>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -it</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> milvus-standalone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> EOF</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /milvus/configs/user.yaml</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">common:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  storage:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    useLoonFFI: true</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">exit</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> milvus-standalone</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p><strong>注意事项</strong>：这是单行道。官方原文：「一旦 Milvus 将数据写入 Storage V3，则不支持降级到无法读取 Storage V3 的 Milvus 版本。」</p><p><strong>参考文档</strong>：<a href="https://milvus.io/docs/zh/install_standalone-docker-compose.md" target="_blank" rel="noreferrer">使用 Docker Compose 运行 Milvus（Linux）</a> · <a href="https://milvus.io/docs/zh/storage-v3.md" target="_blank" rel="noreferrer">存储 V3</a></p><h2 id="_7-1-3-本章小结" tabindex="-1">7.1.3 本章小结 <a class="header-anchor" href="#_7-1-3-本章小结" aria-label="Permalink to &quot;7.1.3 本章小结&quot;">​</a></h2><ul><li>升级只做一件事：备份后，把 standalone 的镜像 tag 换成新版本，<code>pull</code> + <code>up --detach</code>，其余一律不动；</li><li>两个注意事项：消息队列别换；升级失败走备份恢复，不要手动降级镜像；</li><li>Storage V3 默认关闭，用到快照/TEXT/外部 Collection 时在 user.yaml 打开 useLoonFFI 开关，开启后写入数据就回不去旧版。</li></ul><p>环境就绪，下一章开始动真格：湖上一份 Parquet 文件，原地变成一个能查的 Collection。</p><blockquote><p><strong>下一章</strong>：<a href="./7.2-Milvus3.0外部集合与快照.html">7.2　Milvus 3.0 外部集合与快照（实战）</a></p></blockquote>`,34)])])}const u=a(l,[["render",p]]);export{c as __pageData,u as default};
